"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[5058],{19743(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>d,frontMatter:()=>a,metadata:()=>r,toc:()=>l});var o=n(74848),i=n(28453);const a={lang:"en",title:"Chapter 5: You Didn't Meet a Villain, You Met a Structure With No Money to Share",sidebar_label:"5. You Didn't Meet a Villain",slug:"/who-collects-at-the-door/ch05",description:"In early October 2026, CommonWealth Magazine (\u300a\u5929\u4e0b\u96dc\u8a8c\u300b), a Taiwanese business magazine, ran a translated workplace article on how successful p\u2026",keywords:["Who's Collecting at the Door","financialization","Nebula Walker"]},s=void 0,r={id:"\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322/ch05",title:"Chapter 5: You Didn't Meet a Villain, You Met a Structure With No Money to Share",description:"In early October 2026, CommonWealth Magazine (\u300a\u5929\u4e0b\u96dc\u8a8c\u300b), a Taiwanese business magazine, ran a translated workplace article on how successful p\u2026",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322/ch05.md",sourceDirName:"\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322",slug:"/who-collects-at-the-door/ch05",permalink:"/en/docs/who-collects-at-the-door/ch05",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{lang:"en",title:"Chapter 5: You Didn't Meet a Villain, You Met a Structure With No Money to Share",sidebar_label:"5. You Didn't Meet a Villain",slug:"/who-collects-at-the-door/ch05",description:"In early October 2026, CommonWealth Magazine (\u300a\u5929\u4e0b\u96dc\u8a8c\u300b), a Taiwanese business magazine, ran a translated workplace article on how successful p\u2026",keywords:["Who's Collecting at the Door","financialization","Nebula Walker"]},sidebar:"docs",previous:{title:"4. Ten Lunch Boxes",permalink:"/en/docs/who-collects-at-the-door/ch04"},next:{title:"6. How to Lie With Statistics",permalink:"/en/docs/who-collects-at-the-door/ch06"}},h={},l=[{value:"Prologue: A Sentence Missing Its &quot;Not&quot;",id:"prologue-a-sentence-missing-its-not",level:2},{value:"1. The Test: Is There Real Money to Share?",id:"1-the-test-is-there-real-money-to-share",level:2},{value:"2. United in Expansion: A Small Team Inside the Acquirer",id:"2-united-in-expansion-a-small-team-inside-the-acquirer",level:2},{value:"Expansion Doesn&#39;t Guarantee Unity",id:"expansion-doesnt-guarantee-unity",level:3},{value:"3. Quick-Knife Plunder: A Group That Bought Up Contract Factories",id:"3-quick-knife-plunder-a-group-that-bought-up-contract-factories",level:2},{value:"4. Chronic Decline: A Multinational",id:"4-chronic-decline-a-multinational",level:2},{value:"5. Growing on Paper, Shrinking in Cash: A Family Trading Firm",id:"5-growing-on-paper-shrinking-in-cash-a-family-trading-firm",level:2},{value:"6. Back to the Four Techniques",id:"6-back-to-the-four-techniques",level:2},{value:"Summary",id:"summary",level:2}];function c(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",section:"section",sup:"sup",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.em,{children:"Part Two: Why You Can See It and Others Can't"})," \uff5c ",(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door",children:"\ud83d\udcd6 Who's Collecting at the Door"})," \uff5c ",(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/full",children:"\ud83d\udcd6 Full Edition"})]}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.h1,{id:"chapter-5-you-didnt-meet-a-villain-you-met-a-structure-with-no-money-to-share",children:"Chapter 5: You Didn't Meet a Villain, You Met a Structure With No Money to Share"}),"\n",(0,o.jsx)(t.h2,{id:"prologue-a-sentence-missing-its-not",children:'Prologue: A Sentence Missing Its "Not"'}),"\n",(0,o.jsxs)(t.p,{children:["In early October 2026, ",(0,o.jsx)(t.em,{children:"CommonWealth Magazine"}),' (\u300a\u5929\u4e0b\u96dc\u8a8c\u300b), a Taiwanese business magazine, ran a translated workplace article on how successful people "take credit."',(0,o.jsx)(t.sup,{children:(0,o.jsx)(t.a,{href:"#user-content-fn-1",id:"user-content-fnref-1","data-footnote-ref":!0,"aria-describedby":"footnote-label",children:"1"})}),' It was drawn from CNBC and Inc., and the author was an executive coach who works with high performers at Google, Amazon and JPMorgan. She offered four techniques: say "we" before "I," spell out the scale, make invisible work visible, and tie your work to company goals.']}),"\n",(0,o.jsx)(t.p,{children:'The third paragraph of the Chinese version contained this sentence: "You can absolutely claim the credit you deserve while trampling others underfoot." The original surely meant "without trampling others"; the translation dropped the negative and reversed the meaning entirely.'}),"\n",(0,o.jsx)(t.p,{children:'It was only a typo, but in this article it told the truth. Look closely at the examples: "Eric built the back end; I handled the data issues and drove the launch." The person who wrote the code and the person who coordinated are put side by side, but it is the coordinator who reports upward, and the coordinator who controls the story. "Yulan and Theresa put in extraordinary effort, which allowed me to design the strategy." In one sentence, colleagues\' research becomes raw material for your strategy.'}),"\n",(0,o.jsx)(t.p,{children:"\"Say 'we' before 'I'\" looks like modesty; in practice, it is a grammar for transferring credit. Your colleagues have names, but in your sentence they are stepping stones."}),"\n",(0,o.jsx)(t.p,{children:"The deeper problem is that this advice assumes you are standing on a fair stage: credit can be debated in the open, and the better you tell it, the more you get. Only after working at several companies did I learn that this assumption holds in only one kind of structure. In the others, credit has been allocated long before you open your mouth."}),"\n",(0,o.jsxs)(t.p,{children:["Chapter 4 argued that in the same world, some people can see a zero-sum game designed into a place and others can't, because they stand in different positions (see ",(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch04",children:"Chapter 4"}),"). This chapter lays that out using companies I worked in myself: the same person, placed in different structures, sees completely different worlds."]}),"\n",(0,o.jsx)(t.h2,{id:"1-the-test-is-there-real-money-to-share",children:"1. The Test: Is There Real Money to Share?"}),"\n",(0,o.jsx)(t.p,{children:"What decides whether a company can pull together is not, in the first instance, its culture, or even whether it makes money. It is whether there is real money inside it to share."}),"\n",(0,o.jsx)(t.p,{children:"Real money means cash in hand, not numbers on paper. While the pie is still growing, conflict is directed outward: winning other people's business, swallowing other companies. Internally, things are relatively peaceful because there is something to share. When the pie stops growing, conflict can only turn inward."}),"\n",(0,o.jsx)(t.p,{children:"The second axis is how the knife falls when a department has to be cut. Some companies make one clean cut: the decision is made at the top, the pain is concentrated and it has an end. Others refuse to cut and let employees wear each other down, which amounts to outsourcing the layoffs to infighting."}),"\n",(0,o.jsx)(t.p,{children:"Cross these two axes and you get, roughly, four forms. The companies below are anonymized, because all of them are places I worked in or saw firsthand; but I believe that even if not these companies, the same structures play out elsewhere."}),"\n",(0,o.jsx)(t.h2,{id:"2-united-in-expansion-a-small-team-inside-the-acquirer",children:"2. United in Expansion: A Small Team Inside the Acquirer"}),"\n",(0,o.jsx)(t.p,{children:"I spent most of my career in companies that were expanding. It may have been the times, or coincidence, but I didn't know then that this was luck."}),"\n",(0,o.jsx)(t.p,{children:"One of them was a multinational distributor that kept growing through acquisitions. It had several hundred engineers, roughly one or two attached to each company it had bought. My unit was a branch under the Asia headquarters that had started life as a design house: the headquarters had only four engineers, one of them the manager; the regional engineers largely ran their own patches, and agents handled first-line contact and reporting."}),"\n",(0,o.jsx)(t.p,{children:"A small team running a big company's processes. With so few people, each had their own territory; what you did was obvious at a glance, and no one could take it from you. The only people we had to deal with were sales and marketing, and our interests didn't clash much; if someone occasionally stuck a knife in, it never went down to the bone."}),"\n",(0,o.jsx)(t.p,{children:"Integration had its shocks, of course, and people were laid off all along the way. But my unit was the one doing the integrating, not the one being integrated. The fighting happened between the heads of business units, on the org chart; the people laid off were in another city, at another acquired company, and I never met them."}),"\n",(0,o.jsx)(t.p,{children:"Even if someone was replaced because of my existence, we were each just doing our jobs, and that felt a great deal more comfortable. But the comfort itself is worth noting: distance makes cruelty bearable and lets no one feel responsible. The people who decided never met the people laid off, and the people who stayed never met the people who left; the whole thing ran smoothly precisely because everyone was just doing their job."}),"\n",(0,o.jsx)(t.p,{children:"None of this was visible from outside. Everyone used the same email domain and the same brand; to the outside world, it was one company. The real boundary was who headed each business unit, and that line was completely invisible from outside."}),"\n",(0,o.jsx)(t.h3,{id:"expansion-doesnt-guarantee-unity",children:"Expansion Doesn't Guarantee Unity"}),"\n",(0,o.jsx)(t.p,{children:"One point needs stressing here: expansion only provides the conditions for avoiding infighting; it doesn't mean there is none. Managers in expanding companies usually don't want infighting, because internal friction slows down the grab for territory; but structure only sets the conditions, and in the end it comes down to people."}),"\n",(0,o.jsx)(t.p,{children:"I once worked with a large electronics manufacturer in mainland China that was keen on infighting even while expanding. They believed competition drives progress, so they set up a rival for every task and made employees compete; management only had to pick whoever did best and need not concern itself much with the rest."}),"\n",(0,o.jsx)(t.p,{children:"This is not a fifth structure but a management choice: here infighting is not forced out by the structure but deliberately designed as a tool. It saves on the cost of managing, and the price is that employees never have teammates."}),"\n",(0,o.jsx)(t.p,{children:"The model I consider ideal is simple: whatever people want to do, they do it well together, without comparing themselves to each other or fighting. Expansion gives that model room to exist, but whether to use it is management's choice."}),"\n",(0,o.jsx)(t.h2,{id:"3-quick-knife-plunder-a-group-that-bought-up-contract-factories",children:"3. Quick-Knife Plunder: A Group That Bought Up Contract Factories"}),"\n",(0,o.jsx)(t.p,{children:"The second company looked most like the villain. It bought up a large number of small and mid-sized contract manufacturers with idle capacity and then moved into integration: standardize the core processes, centralize R&D, close factories, sell land. It kept selling off assets and kept running a business story; put plainly, it was turning the company into a zombie step by step."}),"\n",(0,o.jsx)(t.p,{children:"It had internal fights too, and used psychological manipulation to push people out. But it did one thing very well: when it wanted to cut a company or a department, it usually did so in one clean cut."}),"\n",(0,o.jsx)(t.p,{children:"The reason is simple: it was an impatient financial operator. To it, a sale was a transaction, and the longer it dragged on, the more the assets lost value; the quick knife was the most efficient way. Psychological manipulation was only a means, used and then put away, never cultivated for years."}),"\n",(0,o.jsx)(t.p,{children:"This is a counterintuitive conclusion: the company that plunders openly is not necessarily the cruelest. A clean cut at least means someone owns the decision; the pain is concentrated, and it ends."}),"\n",(0,o.jsx)(t.h2,{id:"4-chronic-decline-a-multinational",children:"4. Chronic Decline: A Multinational"}),"\n",(0,o.jsx)(t.p,{children:"What really taught me the meaning of dread was the last one: a multinational in chronic decline."}),"\n",(0,o.jsxs)(t.p,{children:["There, credit was not fought over in meeting rooms. The tests you ran and the plans you wrote would be compiled by someone else and handed to the boss's confidant to report first. Then came the race: who speaks first, who produces evidence first, and then lining up the vendors' story. By the time you spoke, the story was set, and any explanation from you only looked like jealousy or credit-grabbing. Why \"you're just jealous\" works so well is left for Chapter 7 (see ",(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch07",children:"Chapter 7"}),")."]}),"\n",(0,o.jsx)(t.p,{children:'What makes the vendors\' account so deadly is that it looks like an independent third party. Your evidence is internal documents; theirs is "people outside say so too," and the boss naturally believes the latter.'}),"\n",(0,o.jsx)(t.p,{children:'Some would say: then keep stricter records, timestamped test reports, versioned plans, a paper trail for external communications. But in that environment even timestamps couldn\'t save you. Your email really was sent, but the other person would swap in a different version and have the vendor make that, and the vendor would make theirs, not yours. The record that counts is not who sent first but whose version the vendor built: what gets built becomes history, and your email becomes "a proposal that was not adopted."'}),"\n",(0,o.jsx)(t.p,{children:"Whom a vendor listens to is decided not by reason but by relationships. Whoever follows the project most closely, calls every day and goes out to dinner becomes the vendor's point of contact. Vendors want steady orders, so they choose the person who sticks closest to them. And so the chain closes: whoever controls the vendor controls execution; whoever controls execution controls the facts; whoever controls the facts controls the credit. However strict the internal rules, they govern only internal documents; they can't govern whom the people outside listen to."}),"\n",(0,o.jsx)(t.p,{children:"A company like this can drag out infighting, attrition and psychological manipulation for years. Being able to drag it out requires conditions of its own: the company must be big enough, and its cash flow steady enough, to afford years of internal friction. The waste never hurts the balance sheet; the costs all fall on employees, so no one is under pressure to call a halt."}),"\n",(0,o.jsx)(t.p,{children:"Dragged out long enough, the politics perpetuate themselves. When infighting becomes the way to survive, the people who play it well rise, and once risen they manage those below with the same methods. In the end the fighting no longer serves any purpose; it is simply how the organization runs."}),"\n",(0,o.jsx)(t.p,{children:"This also explains how good friends who walk arm in arm can stab each other in the back. In an expanding team, the enemy is outside, and the people beside you are your only capital; in an organization that has stopped expanding, the enemy is the people beside you: the same territory, the same boss, the same vendors. The person nearest to you is the one most directly splitting your share of the pie. To report first and line up the story, you need allies; but your allies are also your rivals in the next round of shrinking. The arm around the shoulder and the knife in the back are two sides of the same relationship."}),"\n",(0,o.jsxs)(t.p,{children:["This is exactly the third kind of zero-sum from Chapter 4: zero-sum by design (see ",(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch04",children:"Chapter 4"}),"). The pie may not have been too small in the first place, but once everyone is put in the same queue, and the power to let people through sits with those above, the person standing next to you becomes your rival."]}),"\n",(0,o.jsx)(t.p,{children:'The cruelest part is that no one owns the decision to lay people off. No severance to pay, no one to hold responsible, little legal risk; the role of psychological manipulation is to make you believe that leaving was your own choice. Colleagues become executioners, and the victim becomes a "voluntary resignation." How cruel it gets is proportional not to how greedy the capital is, but to how long the decision is dragged out.'}),"\n",(0,o.jsx)(t.h2,{id:"5-growing-on-paper-shrinking-in-cash-a-family-trading-firm",children:"5. Growing on Paper, Shrinking in Cash: A Family Trading Firm"}),"\n",(0,o.jsx)(t.p,{children:"The first three companies involved three different groups of people. The last case is different: it is one group of people who went through both the rise and the fall."}),"\n",(0,o.jsx)(t.p,{children:"It was a small Chiu Chow (Chaozhou) trading firm that started in my grandfather's generation. It kept expanding and took business from others, including the turf of the Fujianese and local trading groups. Its contracts all faced outward; when it expanded, the whole firm expanded together, so it was united inside, and deeply so. The enemy was outside; the family had no room for infighting."}),"\n",(0,o.jsx)(t.p,{children:"By the later generation, roughly from the 1970s to 2010, the same firm still fell into infighting, because there wasn't enough money to share. Its biggest problem was not that it made no money, but that its receivables could never be collected, and there was no one to sue. The old clients paid their bills; once the clients changed, the debts became impossible to recover. On paper it earned more and more; what actually came in was only small change."}),"\n",(0,o.jsx)(t.p,{children:"This is the fourth form: growing on paper, shrinking in cash. It is the hardest to see, because from outside the company is still making money and still growing; but what everyone is fighting over is money that doesn't exist. The ending is exactly the same as chronic decline."}),"\n",(0,o.jsx)(t.p,{children:"This case corrects a common claim: what decides whether people pull together is not whether the company is expanding, nor whether it is profitable, but whether there is real money to share. And the size of the pie is sometimes entirely outside your control."}),"\n",(0,o.jsx)(t.p,{children:"It is also the strongest evidence in this chapter. The same group of people pulled together when the pie was growing and fought each other when it emptied. The people didn't turn bad; the pie changed."}),"\n",(0,o.jsx)(t.h2,{id:"6-back-to-the-four-techniques",children:"6. Back to the Four Techniques"}),"\n",(0,o.jsxs)(t.p,{children:["Back to the ",(0,o.jsx)(t.em,{children:"CommonWealth"}),' article. Saying "we" before "I," spelling out the scale, making invisible work visible, tying work to company goals: these four techniques work only in the first structure. In the other three, telling it well only gets you robbed faster. In a company in chronic decline, "make invisible work visible" fails completely, because by the time you speak, yours is already the second version.']}),"\n",(0,o.jsxs)(t.table,{children:[(0,o.jsx)(t.thead,{children:(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.th,{children:"Form"}),(0,o.jsx)(t.th,{children:"Real money to share?"}),(0,o.jsx)(t.th,{children:"How the knife falls"}),(0,o.jsx)(t.th,{children:"Where the fighting is"})]})}),(0,o.jsxs)(t.tbody,{children:[(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.td,{children:"United in expansion"}),(0,o.jsx)(t.td,{children:"Yes, the pie is growing"}),(0,o.jsx)(t.td,{children:"On someone else"}),(0,o.jsx)(t.td,{children:"On the org chart, far from you"})]}),(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.td,{children:"Quick-knife plunder"}),(0,o.jsx)(t.td,{children:"Cash from selling off assets"}),(0,o.jsx)(t.td,{children:"One clean cut"}),(0,o.jsx)(t.td,{children:"Brief, used and put away"})]}),(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.td,{children:"Chronic decline"}),(0,o.jsx)(t.td,{children:"No, zero-sum"}),(0,o.jsx)(t.td,{children:"No cut, slow attrition"}),(0,o.jsx)(t.td,{children:"Sitting next to you, year after year"})]}),(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.td,{children:"Growing on paper, shrinking in cash"}),(0,o.jsx)(t.td,{children:"On paper yes, in hand no"}),(0,o.jsx)(t.td,{children:"Dragged out until there isn't enough"}),(0,o.jsx)(t.td,{children:"Among your own people"})]})]})]}),"\n",(0,o.jsx)(t.p,{children:"So when you feel you have run into a villain, don't rush to study the other person's character. Ask yourself four questions first:"}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsx)(t.li,{children:"Is the company still expanding? Is it the business that's expanding, or only the books?"}),"\n",(0,o.jsx)(t.li,{children:"Can the money actually be collected?"}),"\n",(0,o.jsx)(t.li,{children:"When a department has to go, is it one clean cut, or slow attrition?"}),"\n",(0,o.jsx)(t.li,{children:"Who controls the record of credit and execution? Including whom the outside vendors listen to."}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"The answers will tell you which kind of structure you are in, and also which kind of human nature you are seeing."}),"\n",(0,o.jsx)(t.p,{children:"The same person, placed in different structures, sees completely different worlds. What those workplace tips don't tell you is this: what you have run into is often not a villain, but a structure with no money to share."}),"\n",(0,o.jsx)(t.h2,{id:"summary",children:"Summary"}),"\n",(0,o.jsx)(t.p,{children:"The four companies in this chapter answer Part Two's question: why can you see what others can't? People who have spent most of their careers in expanding companies genuinely believe that \"if you explain your work clearly, you get the credit\"; people who have endured a few years in a company in chronic decline know that credit is allocated before anyone opens their mouth. Neither side is lying; they are just standing in different structures."}),"\n",(0,o.jsx)(t.p,{children:"But position is not the only reason. Sometimes the truth is right there in the numbers, and plenty of people can read them, yet everyone who can has a reason not to check. The next chapter begins with a book published in 1954."}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.table,{children:(0,o.jsx)(t.thead,{children:(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.th,{style:{textAlign:"left"},children:(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch04",children:"\u2190 Chapter 4: Ten Lunch Boxes, a Hundred Students"})}),(0,o.jsx)(t.th,{style:{textAlign:"center"},children:(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door",children:"\ud83d\udcd6 Back to Contents"})}),(0,o.jsx)(t.th,{style:{textAlign:"right"},children:(0,o.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch06",children:"Chapter 6: How to Lie With Statistics \u2192"})})]})})}),"\n","\n",(0,o.jsxs)(t.section,{"data-footnotes":!0,className:"footnotes",children:[(0,o.jsx)(t.h2,{className:"sr-only",id:"footnote-label",children:"Footnotes"}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsxs)(t.li,{id:"user-content-fn-1",children:["\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.em,{children:"CommonWealth Magazine"})," (\u300a\u5929\u4e0b\u96dc\u8a8c\u300b), translated workplace article (original from CNBC and Inc.), October 2026. Quotations follow the version accessed on October 4, 2026. [Title, link and original source to be added] ",(0,o.jsx)(t.a,{href:"#user-content-fnref-1","data-footnote-backref":"","aria-label":"Back to reference 1",className:"data-footnote-backref",children:"\u21a9"})]}),"\n"]}),"\n"]}),"\n"]})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var o=n(96540);const i={},a=o.createContext(i);function s(e){const t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);